begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir helpers/fms_visit_assignment_fixture.psql
create function pg_temp.confirm_stage_form(p_visit uuid,p_next uuid) returns jsonb language plpgsql as $$
declare request jsonb; preview jsonb;
begin
  request:=jsonb_build_object('kind','stage_form','instanceStageId',p_visit,'formTemplateId',(select id from visit_assignment_fixture where name='form'),'answers',jsonb_build_object('next_employee',p_next),'outcome','','remark','','checklist','{}'::jsonb);
  preview:=preview_fms_work_transition(request);
  return transition_fms_work_with_audit(request,gen_random_uuid(),'[]',preview->>'fingerprint');
end $$;
insert into visit_assignment_fixture select 'multi_flow',create_fms_revision_with_audit((select id from visit_assignment_fixture where name='flow'));
reset role;
update fms_stages set allow_multiple_doers=true,completion_rule='all_doers',planned_time_rule=jsonb_set(planned_time_rule,'{assignment}','{"mode":"fixed_employee","sources":[],"allowHandoff":false}') where fms_flow_id=(select id from visit_assignment_fixture where name='multi_flow') and stage_key='call';
delete from fms_stage_assignees where fms_stage_id in(select id from fms_stages where fms_flow_id=(select id from visit_assignment_fixture where name='multi_flow') and stage_key='call');
insert into fms_stage_assignees(fms_stage_id,assignee_type,user_profile_id,sort_order) select stage.id,'specific_user',fixture.id,row_number() over() from fms_stages stage cross join visit_assignment_fixture fixture where stage.fms_flow_id=(select id from visit_assignment_fixture where name='multi_flow') and stage.stage_key='call' and fixture.name in ('b','c');
set local role authenticated;
select lives_ok($$select publish_fms_flow_with_audit((select id from visit_assignment_fixture where name='multi_flow'))$$,'multiple fixed doers publish without changing the existing all-doer rule');
insert into visit_assignment_fixture select 'multi_instance',(submit_fms_form_and_progress_with_audit((select id from visit_assignment_fixture where name='form'),jsonb_build_object('next_employee',(select id from visit_assignment_fixture where name='b')),'fms_entry',(select id from fms_starter_assignments where fms_flow_id=(select id from visit_assignment_fixture where name='multi_flow') and user_profile_id=(select id from visit_assignment_fixture where name='a')),gen_random_uuid())->>'instance_id')::uuid;
insert into visit_assignment_fixture select 'multi_visit',work.id from fms_instance_stages work join fms_stages stage on stage.id=work.fms_stage_id where work.fms_instance_id=(select id from visit_assignment_fixture where name='multi_instance') and stage.stage_key='call';
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='b_auth'),true);
select is(pg_temp.confirm_stage_form((select id from visit_assignment_fixture where name='multi_visit'),(select id from visit_assignment_fixture where name='d'))->>'state','awaiting_other_doers','first form records completion while other doers remain');
select is((select status::text from fms_instance_stage_assignees where fms_instance_stage_id=(select id from visit_assignment_fixture where name='multi_visit') and user_profile_id=(select id from visit_assignment_fixture where name='b')),'completed','the submitting actor is actually completed');
select is((select count(*)::integer from fms_instance_stages work join fms_stages stage on stage.id=work.fms_stage_id where work.fms_instance_id=(select id from visit_assignment_fixture where name='multi_instance') and stage.stage_key='demo'),0,'one actor cannot prematurely activate the successor');
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='c_auth'),true);
select throws_ok($$select pg_temp.confirm_stage_form((select id from visit_assignment_fixture where name='multi_visit'),(select id from visit_assignment_fixture where name='e'))$$,'23514','This FMS stage already has a submitted form output','another doer cannot overwrite the shared visit form');
create temporary table completion_request(value jsonb,preview jsonb);
grant all on completion_request to authenticated;
insert into completion_request(value) values(jsonb_build_object('kind','complete','instanceStageId',(select id from visit_assignment_fixture where name='multi_visit'),'outcome','','remark','Employee C confirmed','checklist','{}'::jsonb));
update completion_request set preview=preview_fms_work_transition(value);
select is((select transition_fms_work_with_audit(value,gen_random_uuid(),'[]',preview->>'fingerprint')->>'state' from completion_request),'successors_activated','last required doer completes against the locked form');
reset role;
select is((select count(*)::integer from form_submissions where linked_record_id=(select id from visit_assignment_fixture where name='multi_visit')),1,'the single shared visit form is preserved');
select is((select remark from fms_instance_stage_assignees where fms_instance_stage_id=(select id from visit_assignment_fixture where name='multi_visit') and user_profile_id=(select id from visit_assignment_fixture where name='c')),'Employee C confirmed','each doer retains an individual completion record');
select is((select work.assigned_to from fms_instance_stages work join fms_stages stage on stage.id=work.fms_stage_id where work.fms_instance_id=(select id from visit_assignment_fixture where name='multi_instance') and stage.stage_key='demo'),array[(select id from visit_assignment_fixture where name='d')],'successor uses the immutable form answer');
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='a_auth'),true);
set local role authenticated;
insert into visit_assignment_fixture select 'approval_flow',create_fms_revision_with_audit((select id from visit_assignment_fixture where name='flow'));
reset role;
update fms_stages set step_type='approval',completion_rule='manager_approval',planned_time_rule=jsonb_set(planned_time_rule,'{assignment}','{"mode":"fixed_employee","sources":[],"allowHandoff":false}') where fms_flow_id=(select id from visit_assignment_fixture where name='approval_flow') and stage_key='call';
set local role authenticated;
select lives_ok($$select publish_fms_flow_with_audit((select id from visit_assignment_fixture where name='approval_flow'))$$,'approval workflow publishes');
insert into visit_assignment_fixture select 'approval_instance',(submit_fms_form_and_progress_with_audit((select id from visit_assignment_fixture where name='form'),jsonb_build_object('next_employee',(select id from visit_assignment_fixture where name='b')),'fms_entry',(select id from fms_starter_assignments where fms_flow_id=(select id from visit_assignment_fixture where name='approval_flow') and user_profile_id=(select id from visit_assignment_fixture where name='a')),gen_random_uuid())->>'instance_id')::uuid;
insert into visit_assignment_fixture select 'approval_visit',work.id from fms_instance_stages work join fms_stages stage on stage.id=work.fms_stage_id where work.fms_instance_id=(select id from visit_assignment_fixture where name='approval_instance') and stage.stage_key='call';
select is(pg_temp.confirm_stage_form((select id from visit_assignment_fixture where name='approval_visit'),(select id from visit_assignment_fixture where name='c'))->>'state','awaiting_approval','saving an approval form does not claim successor activation');
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='b_auth'),true);
select throws_ok($$select preview_fms_work_transition(jsonb_build_object('kind','review','instanceStageId',(select id from visit_assignment_fixture where name='approval_visit'),'decision','approved','remark','Forged approval'))$$,'42501',null,'another employee cannot approve through the direct API');
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='a_auth'),true);
truncate completion_request;
insert into completion_request(value) values(jsonb_build_object('kind','review','instanceStageId',(select id from visit_assignment_fixture where name='approval_visit'),'decision','approved','remark','Approved'));
update completion_request set preview=preview_fms_work_transition(value);
select is((select transition_fms_work_with_audit(value,gen_random_uuid(),'[]',preview->>'fingerprint')->>'state' from completion_request),'successors_activated','authorized approval activates the owner from the saved form');
reset role;
select * from finish();
rollback;
